  if (t.includes("\u06A9\u0631\u067E\u0679\u0648") || t.includes("\u0628\u0679 \u06A9\u0648\u0627\u0626\u0646") || t.includes("\u0688\u06CC\u062C\u06CC\u0679\u0644 \u06A9\u0631\u0646\u0633\u06CC")) return "\u06A9\u0631\u067E\u0679\u0648";
