  if (t.includes("\u0648\u0631\u0627\u062B\u062A") || t.includes("\u062A\u0631\u06A9\u06C1") || t.includes("\u062C\u0627\u0626\u06CC\u062F\u0627\u062F")) return "\u0648\u0631\u0627\u062B\u062A";
  if (t.includes("\u0646\u0645\u0627\u0632") || t.includes("\u0642\u0636\u0627\u0621") || t.includes("\u0642\u0635\u0631") || t.includes("\u0633\u062C\u062F\u06C1")) return "\u0646\u0645\u0627\u0632";
  if (t.includes("\u062D\u062C") || t.includes("\u0639\u0645\u0631\u06C1") || t.includes("\u0642\u0631\u0628\u0627\u0646\u06CC")) return "\u062D\u062C";
  if (t.includes("\u067E\u0631\u062F\u06C1") || t.includes("\u062D\u062C\u0627\u0628")) return "\u067E\u0631\u062F\u06C1";
  const clean = topic.replace(/لجنۃ\s*العلماء\s*[:\s]*/g, "").replace(/فتاویٰ\s*لجنۃ\s*العلماء\s*[:\s]*/g, "").replace(/مجھے\s*فتوی\s*(دیں|بتائیں)?\s*(کہ)?/g, "").replace(/کا\s*شرعی\s*حکم\s*(کیا\s*ہے)?/g, "").replace(/کیا\s*حکم\s*ہے/g, "").replace(/شرعی\s*حکم/g, "").replace(/کے\s*احکام\s*(و\s*مسائل)?/g, "").replace(/کا\s*مسنون\s*طریقہ/g, "").replace(/کیا\s*/g, "").replace(/ہے\s*\?/g, "").trim();
