        translation: "\u0628\u06D2 \u0634\u06A9 \u0645\u06C1\u06CC\u0646\u0648\u06BA \u06A9\u06CC \u06AF\u0646\u062A\u06CC \u0627\u0644\u0644\u06C1 \u06A9\u06D2 \u0646\u0632\u062F\u06CC\u06A9 \u0627\u0644\u0644\u06C1 \u06A9\u06CC \u06A9\u062A\u0627\u0628 \u0645\u06CC\u06BA \u0628\u0627\u0631\u06C1 \u0645\u06C1\u06CC\u0646\u06D2 \u06C1\u06D2\u060C \u062C\u0633 \u062F\u0646 \u0633\u06D2 \u0627\u0633 \u0646\u06D2 \u0622\u0633\u0645\u0627\u0646\u0648\u06BA \u0627\u0648\u0631 \u0632\u0645\u06CC\u0646 \u06A9\u0648 \u067E\u06CC\u062F\u0627 \u0641\u0631\u0645\u0627\u06CC\u0627\u060C \u0627\u0646 \u0645\u06CC\u06BA \u0633\u06D2 \u0686\u0627\u0631 \u062D\u0631\u0645\u062A \u0648\u0627\u0644\u06D2 \u06C1\u06CC\u06BA\u06D4 (\u0633\u0648\u0631\u06C3 \u0627\u0644\u062A\u0648\u0628\u06C3: 36)",
