            "\u0644\u062C\u0646\u06C3 \u0627\u0644\u0639\u0644\u0645\u0627\u0621: \u063A\u0633\u0644 \u06A9\u06D2 \u0641\u0631\u0627\u0626\u0636 \u0627\u0648\u0631 \u0633\u0646\u062A\u06CC\u06BA \u06A9\u0648\u0646 \u0633\u06CC \u06C1\u06CC\u06BA\u061F",
