          keyTakeaway: "\u0639\u0644\u0627\u062C \u06A9\u06D2 \u0627\u0646\u062C\u06A9\u0634\u0646\u060C \u0627\u0646\u06C1\u06CC\u0644\u0631\u060C \u0645\u0633\u0648\u0627\u06A9 \u0627\u0648\u0631 \u062E\u0648\u0646 \u06A9\u06D2 \u0679\u06CC\u0633\u0679 \u0633\u06D2 \u0631\u0648\u0632\u06C1 \u0646\u06C1\u06CC\u06BA \u0679\u0648\u0679\u062A\u0627\u060C \u062C\u0628\u06A9\u06C1 \u0637\u0627\u0642\u062A \u06A9\u06CC \u06AF\u0644\u0648\u06A9\u0648\u0632 \u0688\u0631\u067E \u0633\u06D2 \u0631\u0648\u0632\u06C1 \u0679\u0648\u0679 \u062C\u0627\u062A\u0627 \u06C1\u06D2\u06D4",
