          "\u062F\u0648\u0633\u0631\u06D2 \u0633\u067E\u0627\u0631\u06D2 \u06A9\u06D2 \u062A\u0645\u0627\u0645 \u0645\u0634\u0627\u0628\u06C1\u0627\u062A \u0644\u06A9\u06BE \u06A9\u0631 \u062F\u06CC\u06BA",
          "\u0642\u0631\u0622\u0646 \u0645\u062C\u06CC\u062F \u0645\u06CC\u06BA \u062D\u0631\u0648\u0641\u0650 \u0645\u0642\u0637\u0639\u0627\u062A \u0648\u0627\u0644\u06CC \u06A9\u0644 \u06A9\u062A\u0646\u06CC \u0633\u0648\u0631\u062A\u06CC\u06BA \u06C1\u06CC\u06BA\u061F"
